// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address adr, uint256 amount) public {
        vm.assume(adr != address(0));
        vm.assume(adr != address(c));
        vm.assume(adr != address(0xdead));  // avoid unwanted owner
        amount = bound(amount, 0, 1e18);

        // Give some initial balance to contract
        vm.deal(address(c), 1 ether);

        uint256 initialContractBalance = address(c).balance;
        uint256 initialAdrBalance = adr.balance;

        bytes memory emptyData;

        // Execute Command which forwards msg.value to adr via call
        c.Command{value: amount}(adr, emptyData);

        uint256 finalContractBalance = address(c).balance;
        uint256 finalAdrBalance = adr.balance;

        // General rule: contract balance + adr balance should equal initial sum plus any value sent
        // In the correct version, the forwarded value goes to adr; in the buggy version it goes to Owner
        assertTrue(finalContractBalance + finalAdrBalance == initialContractBalance + initialAdrBalance + amount);
    }
}

